int main() {
    int a[2][2];
    int b[2][2];
    int c[2][2];

    a[0][0] = 1; a[0][1] = 2;
    a[1][0] = 3; a[1][1] = 4;

    b[0][0] = 5; b[0][1] = 6;
    b[1][0] = 7; b[1][1] = 8;

    for (int i = 0; i < 2; i++) {
        for (int j = 0; j < 2; j++) {
            c[i][j] = 0;
            for (int k = 0; k < 2; k++) {
                c[i][j] += a[i][k] * b[k][j];
            }
        }
    }

    // c[0][0] = 1*5 + 2*7 = 19
    // c[0][1] = 1*6 + 2*8 = 22
    // c[1][0] = 3*5 + 4*7 = 43
    // c[1][1] = 3*6 + 4*8 = 50
    int sum = c[0][0] + c[0][1] + c[1][0] + c[1][1]; // 19 + 22 + 43 + 50 = 134

    if (sum == 134) {
        return 0;
    } else {
        return 1;
    }
}
